const TIMES = ['5 phút trước', '12 phút trước', '26 phút trước', '1 giờ trước', '2 giờ trước', '5 giờ trước', 'Hôm qua', '2 ngày trước'];

import { CONTENT } from './content';

function buildChapters(seed, count, slug) {
  const extra = CONTENT[slug] || {};
  const titles = extra.titles || [];
  const intro = extra.intro || [];
  const chapters = [];
  for (let i = 0; i < count; i++) {
    const paras = [];
    if (i === 0 && intro.length) paras.push(...intro);
    while (paras.length < 10) paras.push(PROSE[(seed * 3 + i * 5 + paras.length) % PROSE.length]);
    chapters.push({
      num: i + 1,
      title: `Chương ${i + 1}: ${titles[i] || CH_TITLES[(seed + i) % CH_TITLES.length]}`,
      time: TIMES[(seed + i) % TIMES.length],
      paras,
    });
  }
  return chapters;
}

